import FormModal from 'flarum/common/components/FormModal';
import extractText from 'flarum/common/utils/extractText';
import Button from 'flarum/common/components/Button';
import { t } from '../../common/t';
import { adminSend } from '../api';
/** Enter a final score: every moneyline, spread and total is graded from it, once. */
export default class ScoreModal extends FormModal {
  home = '';
  away = '';
  className() {
    return 'Modal--small';
  }
  title() {
    return t('admin.score.title', {
      name: this.attrs.event.name
    });
  }
  content() {
    const e = this.attrs.event;
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, t('admin.score.help')), m("div", {
      className: "Form-group"
    }, m("label", null, e.away?.name), m("input", {
      className: "FormControl",
      type: "number",
      min: "0",
      value: this.away,
      oninput: ev => this.away = ev.target.value
    })), m("div", {
      className: "Form-group"
    }, m("label", null, e.home?.name), m("input", {
      className: "FormControl",
      type: "number",
      min: "0",
      value: this.home,
      oninput: ev => this.home = ev.target.value
    })), m(Button, {
      className: "Button Button--primary",
      type: "submit",
      loading: this.loading,
      disabled: this.home === '' || this.away === ''
    }, t('admin.score.submit')));
  }
  onsubmit(e) {
    e.preventDefault();
    if (!confirm(extractText(t('admin.score.confirm', {
      away: this.away,
      home: this.home
    })))) return;
    this.loading = true;
    adminSend('POST', `/events/${this.attrs.event.id}/score`, {
      home: parseInt(this.home, 10),
      away: parseInt(this.away, 10)
    }).then(() => {
      this.attrs.onsave();
      this.hide();
    }).catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-longshot', 'admin/components/ScoreModal', ScoreModal);