import FormModal from 'flarum/common/components/FormModal';
import extractText from 'flarum/common/utils/extractText';
import Button from 'flarum/common/components/Button';
import Select from 'flarum/common/components/Select';
import { t } from '../../common/t';
import { adminSend } from '../api';
/** Name the result of a custom market, option by option. */
export default class ResolveModal extends FormModal {
  results = {};
  className() {
    return 'Modal--small';
  }
  title() {
    return t('admin.resolve.title', {
      market: this.attrs.market.label
    });
  }
  content() {
    const options = {
      win: t('admin.resolve.win'),
      lose: t('admin.resolve.lose'),
      void: t('admin.resolve.void')
    };
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, t('admin.resolve.help')), this.attrs.market.selections.map(s => m("div", {
      className: "Form-group"
    }, m("label", null, s.label), m(Select, {
      options: options,
      value: this.results[s.id] ?? 'lose',
      onchange: v => this.results[s.id] = v
    }))), m(Button, {
      className: "Button Button--primary",
      type: "submit",
      loading: this.loading
    }, t('admin.resolve.submit')));
  }
  onsubmit(e) {
    e.preventDefault();
    const results = {};
    this.attrs.market.selections.forEach(s => results[s.id] = this.results[s.id] ?? 'lose');
    if (!confirm(extractText(t('admin.resolve.confirm')))) return;
    this.loading = true;
    adminSend('POST', `/markets/${this.attrs.market.id}/resolve`, {
      results
    }).then(() => {
      this.attrs.onsave();
      this.hide();
    }).catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-longshot', 'admin/components/ResolveModal', ResolveModal);